window.products.push({"id":545956,"name":"Sleeplace Mattress, King","category":"homeandappliances","retail price":479.36,"sale price":null,"image":"https://m.media-amazon.com/images/I/81xIWxu7p1L._AC_SL1500_.jpg","description":"SLEEPLACE 13 in Galaxy Euro Box Top Spring Mattress 13SM01 is designed to satisfy the need for contoured support of your back while you sleep. This is featured by: tempered steel independently-encased coils whose particularity is to conform to the curves of your body creating an equal weight distribution, hence relieving any pressure points along your neck, shoulders, back and hips. Another advantage of Independently-encased coils is the elimination of motion disturbance, so that if your partner moves throughout the night, you will never even know they are there. To ensure that this mattress lasts many years, its coils are protected by multi HD and Memory foam layers which add to unparalleled quality and incredible comfort.","images":["https://m.media-amazon.com/images/I/81xIWxu7p1L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Sleeplace","source_asin":"B077G2DN5K","category_path":"Home & Kitchen"},"sku":"BM-545956","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B077G2DN5K","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B077G2DN5K","price_pending":true,"merchant_ready":false});
